<?php
declare(strict_types=1);
require_once __DIR__.'/config/coach_network.php';
$error=null;$success=null;$user=null;$coaches=[];$levels=[];$profiles=[];$edit=null;$csrf='';
function cn_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
try{
 $pdo=role_portal_db();coach_network_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);
 if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php?permission=users.manage');exit;}
 $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  security_step17_verify_csrf((string)($_POST['csrf']??''));$coachId=max(0,(int)($_POST['coach_user_id']??0));$parentId=max(0,(int)($_POST['parent_coach_user_id']??0));$levelId=max(0,(int)($_POST['level_label_id']??0));$memberId=trim((string)($_POST['herbalife_member_id']??''));$joined=trim((string)($_POST['joined_at']??''));$status=(string)($_POST['network_status']??'active');$notes=trim((string)($_POST['notes']??''));
  if(!in_array($status,['active','inactive'],true))$status='active';
  $q=$pdo->prepare("SELECT COUNT(*) FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.id=? AND a.role_code='coach' AND u.is_active=1 AND a.is_active=1");$q->execute([$orgId,$coachId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Choose a valid active Coach account.');
  if($parentId>0){$q->execute([$orgId,$parentId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Choose a valid Parent/Upline Coach.');if(coach_network_would_cycle($pdo,$orgId,$coachId,$parentId))throw new RuntimeException('This assignment would create a circular Coach hierarchy.');}
  $q=$pdo->prepare("SELECT COUNT(*) FROM coach_level_labels WHERE organization_id=? AND id=? AND status='active'");$q->execute([$orgId,$levelId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Choose a valid Herbalife level.');
  $s=$pdo->prepare("INSERT INTO coach_network_profiles(organization_id,coach_user_id,parent_coach_user_id,level_label_id,herbalife_member_id,joined_at,network_status,notes,assigned_by) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE parent_coach_user_id=VALUES(parent_coach_user_id),level_label_id=VALUES(level_label_id),herbalife_member_id=VALUES(herbalife_member_id),joined_at=VALUES(joined_at),network_status=VALUES(network_status),notes=VALUES(notes),assigned_by=VALUES(assigned_by)");$s->execute([$orgId,$coachId,$parentId?:null,$levelId,$memberId?:null,$joined?:null,$status,$notes?:null,(int)$user['id']]);
  security_step17_audit($pdo,(int)$user['id'],'coach_network_saved','coach',$coachId,['parent_coach_user_id'=>$parentId?:null,'level_label_id'=>$levelId,'status'=>$status]);$success='Coach hierarchy and Herbalife level saved.';
 }
 $q=$pdo->prepare("SELECT u.id,u.full_name,u.email FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE a.role_code='coach' AND u.is_active=1 AND a.is_active=1 ORDER BY u.full_name");$q->execute([$orgId]);$coaches=$q->fetchAll();
 $q=$pdo->prepare("SELECT * FROM coach_level_labels WHERE organization_id=? AND status='active' ORDER BY sort_order,level_name");$q->execute([$orgId]);$levels=$q->fetchAll();
 $q=$pdo->prepare("SELECT p.*,u.full_name coach_name,u.email,l.level_name,l.level_group,parent.full_name parent_name,(SELECT COUNT(*) FROM coach_network_profiles c WHERE c.organization_id=p.organization_id AND c.parent_coach_user_id=p.coach_user_id) direct_coaches,(SELECT COUNT(*) FROM customer_membership_profiles m WHERE m.organization_id=p.organization_id AND m.coach_user_id=p.coach_user_id) customers FROM coach_network_profiles p JOIN system_users u ON u.id=p.coach_user_id LEFT JOIN system_users parent ON parent.id=p.parent_coach_user_id LEFT JOIN coach_level_labels l ON l.id=p.level_label_id WHERE p.organization_id=? ORDER BY l.sort_order DESC,u.full_name");$q->execute([$orgId]);$profiles=$q->fetchAll();
 $editId=max(0,(int)($_GET['edit']??0));foreach($profiles as $row)if((int)$row['coach_user_id']===$editId)$edit=$row;
}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Coach Network Manager</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>
.cn-grid{display:grid;grid-template-columns:minmax(360px,.42fr) minmax(0,.58fr);gap:14px;margin-top:14px;align-items:start}.cn-form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cn-form label{display:grid;gap:5px;color:#626677;font-size:.67rem;font-weight:800}.cn-form input,.cn-form select,.cn-form textarea{width:100%;min-height:41px;padding:9px 10px;border:1px solid #dcdeea;border-radius:10px;background:#fff}.cn-form .wide{grid-column:1/-1}.cn-form textarea{min-height:82px}.cn-form button{grid-column:1/-1;min-height:42px;border:0;border-radius:10px;background:#5a47d6;color:#fff;font-weight:850}.cn-levels{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.cn-levels span{padding:6px 9px;border-radius:999px;background:#f0edff;color:#5040bd;font-size:.58rem;font-weight:850}.cn-table{min-width:820px!important}.cn-table small{display:block;margin-top:3px;color:#7b7f8c}.cn-count{display:inline-flex;padding:5px 7px;border-radius:8px;background:#f4f3fb;color:#5247a6;font-size:.6rem;font-weight:800}@media(max-width:1050px){.cn-grid{grid-template-columns:1fr}}@media(max-width:620px){.cn-form{grid-template-columns:1fr}.cn-form .wide{grid-column:auto}}
</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt=""><span><strong>Healthcare Wellness Club</strong><small>Coach Network & Herbalife Levels</small></span></a><div class="os-top-actions"><a class="os-btn" href="role_accounts.php">Role Accounts</a><a class="os-btn primary" href="customer_membership_manager.php">Club Members</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><section class="os-hero"><div class="os-kicker">COACH NETWORK • UPLINE / DOWNLINE</div><h1>Connect every Coach to a Parent Coach and an official recognition level.</h1><p>Coach remains the internal Business OS role. Herbalife level is stored separately for recognition and reporting; it does not automatically change permissions, prices, earnings or qualification.</p><div class="os-status-row"><span class="os-chip good"><?=count($profiles)?> configured coaches</span><span class="os-chip"><?=count($levels)?> levels</span></div><div class="cn-levels"><?php foreach($levels as $l):?><span><?=cn_h($l['level_name'])?></span><?php endforeach;?></div></section><?php if($error):?><div class="pp-alert bad"><?=cn_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?=cn_h($success)?></div><?php endif;?><section class="cn-grid"><article class="os-card"><h2><?=$edit?'Update Coach':'Configure Coach'?></h2><p>Assign level and optional Parent/Upline Coach.</p><form method="post" class="cn-form"><input type="hidden" name="csrf" value="<?=cn_h($csrf)?>"><label class="wide">Coach Account<select name="coach_user_id" required><option value="">Choose Coach</option><?php foreach($coaches as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($edit['coach_user_id']??0)===(int)$c['id'])?'selected':''?>><?=cn_h($c['full_name'].' • '.$c['email'])?></option><?php endforeach;?></select></label><label>Parent / Upline Coach<select name="parent_coach_user_id"><option value="">Top level / Administrator</option><?php foreach($coaches as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($edit['parent_coach_user_id']??0)===(int)$c['id'])?'selected':''?>><?=cn_h($c['full_name'])?></option><?php endforeach;?></select></label><label>Herbalife Level<select name="level_label_id" required><option value="">Choose level</option><?php foreach($levels as $l):?><option value="<?=(int)$l['id']?>" <?=((int)($edit['level_label_id']??0)===(int)$l['id'])?'selected':''?>><?=cn_h($l['level_name'])?></option><?php endforeach;?></select></label><label>Herbalife Member ID<input name="herbalife_member_id" value="<?=cn_h($edit['herbalife_member_id']??'')?>"></label><label>Joined Date<input type="date" name="joined_at" value="<?=cn_h($edit['joined_at']??date('Y-m-d'))?>"></label><label>Status<select name="network_status"><option value="active">Active</option><option value="inactive" <?=($edit['network_status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><label class="wide">Internal Notes<textarea name="notes"><?=cn_h($edit['notes']??'')?></textarea></label><button>Save Coach Network →</button></form></article><article class="os-card"><h2>Coach Network Register</h2><p>Customers remain assigned to their Coach; Coaches can additionally report to another Coach.</p><div class="pp-table-wrap"><table class="pp-table cn-table"><thead><tr><th>Coach</th><th>Level</th><th>Parent/Upline</th><th>Direct Coaches</th><th>Customers</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($profiles as $p):?><tr><td><b><?=cn_h($p['coach_name'])?></b><small><?=cn_h($p['herbalife_member_id']?:$p['email'])?></small></td><td><span class="pp-badge"><?=cn_h($p['level_name']?:'Not assigned')?></span></td><td><?=cn_h($p['parent_name']?:'Top level')?></td><td><span class="cn-count"><?=(int)$p['direct_coaches']?></span></td><td><span class="cn-count"><?=(int)$p['customers']?></span></td><td><?=cn_h(strtoupper($p['network_status']))?></td><td><a href="?edit=<?=(int)$p['coach_user_id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$profiles):?><tr><td colspan="7">No Coach hierarchy configured yet.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Important:</strong> Recognition labels are administrative records based on official Herbalife naming. Qualification and earnings are not calculated or guaranteed by this page.</div></main><script src="assets/business-collapsible.js?v=20260820-2" defer></script></body></html>
